   </main>
   <div class="toast" id="toast" role="status"></div>
   <div class="modal-backdrop" id="modalBackdrop"><div class="modal" role="dialog" aria-modal="true"><h2 id="modalTitle">Como jogar</h2><p id="modalText"></p><div class="modal-actions"><button class="modal-btn" id="modalCancel">Voltar</button><button class="modal-btn danger" id="modalConfirm" style="display:none">Reiniciar</button></div></div></div>
   <script>
+    const SAVE_KEY='click-lab-save-v1';
+    const upgrades=[
+      {id:'finger',name:'Dedo biônico',desc:'Mais força em cada toque',icon:'☝️',kind:'click',cost:15,gain:1,scale:1.16},
+      {id:'glove',name:'Luva de precisão',desc:'Cliques mais poderosos',icon:'🧤',kind:'click',cost:120,gain:6,scale:1.17},
+      {id:'intern',name:'Estagiário',desc:'Gera energia automaticamente',icon:'🧑‍🔬',kind:'auto',cost:35,gain:1,scale:1.16},
+      {id:'drone',name:'Drone coletor',desc:'Uma frota incansável',icon:'🛸',kind:'auto',cost:250,gain:8,scale:1.17},
+      {id:'reactor',name:'Micro reator',desc:'Energia limpa em escala',icon:'⚛️',kind:'auto',cost:1800,gain:55,scale:1.18},
+      {id:'quantum',name:'Núcleo quântico',desc:'Dobra as leis da produção',icon:'💠',kind:'auto',cost:14000,gain:360,scale:1.19}
+    ];
+    const goals=[{n:'Primeiro clique',at:1,icon:'✳'},{n:'Ritmo constante',at:1000,icon:'⌁'},{n:'Pequena fábrica',at:10000,icon:'⚙'},{n:'Império',at:50000,icon:'✦'}];
+    const fresh=()=>({energy:0,runTotal:0,lifetime:0,prestige:0,levels:{},unlocked:[],sound:false,last:Date.now()});
+    let state=fresh(),filter='all',combo=1,lastClick=0,comboTimer=null,toastTimer=null,audioCtx=null;
+    const $=s=>document.querySelector(s);
+    const fmt=n=>{if(!Number.isFinite(n))return'∞';if(n<1000)return Math.floor(n).toLocaleString('pt-BR');const units=[' mil',' mi',' bi',' tri',' qua'];let i=-1;while(n>=1000&&i<units.length-1){n/=1000;i++}return n.toLocaleString('pt-BR',{maximumFractionDigits:n<10?2:1})+units[i]};
+    const number=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:n<10?1:0});
+    const level=id=>state.levels[id]||0;
+    const multiplier=()=>1+state.prestige*.25;
+    const clickPower=()=>((1+level('finger')*upgrades[0].gain+level('glove')*upgrades[1].gain)*multiplier());
+    const cps=()=>upgrades.filter(u=>u.kind==='auto').reduce((sum,u)=>sum+level(u.id)*u.gain,0)*multiplier();
+    function save(){state.last=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){}}
+    function load(){try{const raw=localStorage.getItem(SAVE_KEY);if(raw){const parsed=JSON.parse(raw);state={...fresh(),...parsed,levels:{...fresh().levels,...parsed.levels}}}}catch(e){state=fresh()}
+      if(state.energy<0||!Number.isFinite(state.energy))state.energy=0;
+      const elapsed=Math.min(4*60*60,Math.max(0,(Date.now()-(state.last||Date.now()))/1000));
+      const away=Math.floor(cps()*elapsed*.65);if(away>0){state.energy+=away;state.runTotal+=away;state.lifetime+=away;setTimeout(()=>notify(`Enquanto você estava fora, sua fábrica produziu ${fmt(away)} energia.`),500)}
+      state.last=Date.now();
+    }
+    function notify(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
+    function playTone(){if(!state.sound)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=500+Math.random()*180;gain.gain.setValueAtTime(.035,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.09);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.09)}catch(e){}}
+    function buy(u){const cost=Math.ceil(u.cost*Math.pow(u.scale,level(u.id)));if(state.energy+1e-8<cost)return false;state.energy-=cost;state.levels[u.id]=level(u.id)+1;playTone();notify(`${u.name} aprimorado para nível ${level(u.id)}!`);render();return true}
+    function makeUpgrade(u){const lv=level(u.id),cost=Math.ceil(u.cost*Math.pow(u.scale,lv)),can=state.energy>=cost;const card=document.createElement('button');card.className=`upgrade ${can?'affordable':''}`;card.type='button';card.setAttribute('aria-label',`${u.name}, nível ${lv}, custa ${fmt(cost)} energia`);card.innerHTML=`${lv?`<span class="upgrade-level">N${lv}</span>`:''}<span class="upgrade-icon">${u.icon}</span><span class="upgrade-info"><span class="upgrade-name">${u.name}</span><span class="upgrade-desc">${u.desc}</span></span><span class="upgrade-buy"><span class="upgrade-cost">${fmt(cost)} ✳</span><span class="upgrade-gain">+${number(u.gain)} ${u.kind==='click'?'toque':'/s'}</span></span>`;card.addEventListener('click',()=>buy(u));return card}
+    function renderShop(){const list=$('#upgradeList');list.replaceChildren();let visible=upgrades.filter(u=>filter==='all'||u.kind===filter);visible.forEach(u=>list.append(makeUpgrade(u)));const owned=upgrades.filter(u=>level(u.id)>0).length;$('#shopCount').textContent=`${owned}/6`}
+    function render(){
+      $('#total').textContent=fmt(state.energy);$('#cps').textContent=`${number(cps())} / s`;$('#perClick').textContent=`+${number(clickPower())}`;$('#multiplier').textContent=`×${multiplier().toFixed(1)}`;
+      const ranks=['ESTAGIÁRIO','OPERADOR','ENGENHEIRO','DIRETOR','VISIONÁRIO','LENDA'];const rung=Math.min(ranks.length-1,Math.floor(Math.log10(Math.max(1,state.lifetime))/1.2));$('#rank').textContent=`${ranks[rung]} · NIV. ${String(rung+1).padStart(2,'0')}`;
+      $('#clickBoost').textContent=`+${number(clickPower())} energia`;$('#combo').textContent=`×${combo.toFixed(1).replace('.',',')}`;
+      const completed=goals.filter(g=>state.lifetime>=g.at).length;$('#milestoneCount').textContent=`${completed} / ${goals.length}`;$('#milestoneFill').style.width=`${completed/goals.length*100}%`;
+      const ms=$('#milestones');ms.replaceChildren();goals.forEach(g=>{const done=state.lifetime>=g.at;const el=document.createElement('div');el.className=`milestone ${done?'done':''}`;el.innerHTML=`<span class="milestone-icon">${g.icon}</span><span><span class="milestone-name">${g.n}</span><span class="milestone-at">${fmt(g.at)} energia</span></span>`;ms.append(el)});
+      const shards=Math.floor(state.runTotal/50000),ready=shards>0;$('#prestigeBtn').classList.toggle('ready',ready);$('#prestigeBtn').textContent=`ASCENDER · +${shards}`;$('#prestigeText').innerHTML=ready?`Pronto! Ganhe <b>${shards} fragmento${shards===1?'':'s'}</b> e multiplique sua produção.`:`Alcance <b>${fmt(Math.max(0,50000-state.runTotal))}</b> energia nesta rodada para ascender.`;$('#prestigeFill').style.width=`${Math.min(100,state.runTotal/50000*100)}%`;
+      renderShop();$('#soundBtn').style.color=state.sound?'var(--lime)':'';
+    }
+    function addEnergy(amount){if(!(amount>0))return;state.energy+=amount;state.runTotal+=amount;state.lifetime+=amount}
+    function clickMachine(event){const now=Date.now();combo=now-lastClick<850?Math.min(2.5,combo+.15):1;lastClick=now;clearTimeout(comboTimer);comboTimer=setTimeout(()=>{combo=1;render()},950);const amount=clickPower()*combo;addEnergy(amount);playTone();const zone=$('#machineZone'),rect=zone.getBoundingClientRect();const x=event&&event.clientX?event.clientX-rect.left:rect.width/2;const y=event&&event.clientY?event.clientY-rect.top:rect.height/2;const floater=document.createElement('div');floater.className='click-feedback';floater.textContent=`+${number(amount)}`;floater.style.left=`${x}px`;floater.style.top=`${y}px`;zone.append(floater);floater.addEventListener('animationend',()=>floater.remove());const btn=$('#clicker');btn.classList.add('pressed');setTimeout(()=>btn.classList.remove('pressed'),100);render()}
+    function buyMax(){let bought=0;let safety=0;while(safety++<1000){const affordable=upgrades.map(u=>({u,cost:Math.ceil(u.cost*Math.pow(u.scale,level(u.id)))})).filter(x=>x.cost<=state.energy).sort((a,b)=>a.cost-b.cost);if(!affordable.length)break;const {u}=affordable[0];state.energy-=Math.ceil(u.cost*Math.pow(u.scale,level(u.id)));state.levels[u.id]=level(u.id)+1;bought++}if(bought){playTone();notify(`${bought} upgrade${bought===1?'':'s'} comprado${bought===1?'':'s'}!`);render()}else notify('Ainda falta energia para o próximo upgrade.')}

input.newString:
    function buyMax(){let bought=0;let safety=0;while(safety++<1000){const affordable=upgrades.map(u=>({u,cost:Math.ceil(u.cost*Math.pow(u.scale,level(u.id)))})).filter(x=>x.cost<=state.energy).sort((a,b)=>a.cost-b.cost);if(!affordable.length)break;const {u}=affordable[0];state.energy-=Math.ceil(u.cost*Math.pow(u.scale,level(u.id)));state.levels[u.id]=level(u.id)+1;bought++}if(bought){playTone();notify(`${bought} upgrade${bought===1?'':'s'} comprado${bought===1?'':'s'}!`);render()}else notify('Ainda falta energia para o próximo upgrade.')}
    function openModal(title,text,confirmLabel,onConfirm){$('#modalTitle').textContent=title;$('#modalText').textContent=text;const confirm=$('#modalConfirm');confirm.style.display=confirmLabel?'inline-block':'none';confirm.textContent=confirmLabel||'';confirm.onclick=()=>{closeModal();if(onConfirm)onConfirm()};$('#modalBackdrop').classList.add('open')}
    function closeModal(){$('#modalBackdrop').classList.remove('open')}
    function ascend(){const shards=Math.floor(state.runTotal/50000);if(shards<1){notify('Junte 50 mil de energia nesta rodada para ascender.');return}openModal('Ascender ao próximo nível?',`Sua fábrica será reiniciada: você perderá ${fmt(state.energy)} energia e todos os upgrades desta rodada. Em troca, recebe ${shards} fragmento${shards===1?'':'s'} de prestígio, aumentando permanentemente sua produção em ${shards*25}%.`, 'ASCENDER',()=>{state.prestige+=shards;state.energy=0;state.runTotal=0;state.levels={};save();render();notify(`Ascensão concluída! Multiplicador permanente ×${multiplier().toFixed(2)}.`)})}
    $('#clicker').addEventListener('click',clickMachine);
    $('#buyMax').addEventListener('click',buyMax);
    $('#prestigeBtn').addEventListener('click',ascend);
    $('#soundBtn').addEventListener('click',()=>{state.sound=!state.sound;if(state.sound)playTone();render();save()});
    $('#helpBtn').addEventListener('click',()=>openModal('Como jogar','Toque no grande núcleo ou aperte ESPAÇO para gerar energia. Compre upgrades na árvore para fortalecer seus cliques e automatizar a produção. O progresso salva sozinho, inclusive enquanto você está fora (até 4 horas). Ao atingir 50 mil de energia em uma rodada, você pode ascender: reinicia os upgrades em troca de um bônus permanente.'));
    $('#resetBtn').addEventListener('click',()=>openModal('Apagar todo o progresso?', 'Isso apaga energia, upgrades e fragmentos de prestígio. Esta ação não pode ser desfeita.', 'APAGAR TUDO',()=>{state=fresh();save();render();notify('Novo laboratório iniciado. Boa sorte!')}));
    $('#modalCancel').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});
    document.querySelectorAll('.tab').forEach(tab=>tab.addEventListener('click',()=>{filter=tab.dataset.tab;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===tab));renderShop()}));
    window.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.repeat&&!['BUTTON','INPUT'].includes(document.activeElement.tagName)&&!$('#modalBackdrop').classList.contains('open')){e.preventDefault();clickMachine()}if(e.key==='Escape')closeModal()});
    window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});
    load();render();if(state.energy>0){}let lastTick=Date.now();setInterval(()=>{const now=Date.now(),dt=Math.min(.5,(now-lastTick)/1000);lastTick=now;addEnergy(cps()*dt);render()},200);setInterval(save,5000);
  </script>
</body>
</html>

